(2981358, 418471, 27164, '<td valign="top">This is great!  Nice perspective and composition.  I suspect this will do quite well, good luck.</td>', 'This is great!  Nice perspective and composition.  I suspect this will do quite well, good luck.', '2006-11-01 01:37:56.000000', NULL, 1),
(2981364, 419496, 66668, '<td valign="top">Vertical?</td>', 'Vertical?', '2006-11-01 01:39:08.000000', NULL, 1),
(2981366, 419383, 64933, '<td valign="top">I really like how you enhanced the image by making the background flow towards the tree, but I would have rated it higher if that bench with the person on it wasn''t there. The red distracts and the bench being tilted like it is makes it seem less real and beautiful.</td>', 'I really like how you enhanced the image by making the background flow towards the tree, but I would have rated it higher if that bench with the person on it wasn''t there. The red distracts and the bench being tilted like it is makes it seem less real and beautiful.', '2006-11-01 01:39:21.000000', NULL, 1),
(2981367, 420185, 65779, '<td valign="top">Wrong challenge unfortunately</td>', 'Wrong challenge unfortunately', '2006-11-01 01:39:32.000000', NULL, 1),
