(2981616, 417363, 30861, '<td valign="top">This is very sweet. Understated and evocative, lovely muted tonalities.</td>', 'This is very sweet. Understated and evocative, lovely muted tonalities.', '2006-11-01 02:52:45.000000', NULL, 1),
(2981622, 418992, 30861, '<td valign="top">Very nice, really :-) I wish the sky had some gradient added to balance, and perhaps the foreground gradient weren''t so dark... But beautifully seen.</td>', 'Very nice, really :-) I wish the sky had some gradient added to balance, and perhaps the foreground gradient weren''t so dark... But beautifully seen.', '2006-11-01 02:55:24.000000', NULL, 1),
