INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2981882, 419289, 58567, '<td valign="top">Over the top and wonderful...well executed all around!</td>', 'Over the top and wonderful...well executed all around!', '2006-11-01 04:15:28.000000', NULL, 1),
(2981887, 420514, 58567, '<td valign="top">You got down and glued those leaves to the path.....admit it!  Delightful shot!</td>', 'You got down and glued those leaves to the path.....admit it!  Delightful shot!', '2006-11-01 04:16:47.000000', NULL, 1),
