(2981901, 417629, 58567, '<td valign="top">Nicely done...I would have tricked up the sky a little more....ahhhh maybe not...it''s growing on me while I type :)</td>', 'Nicely done...I would have tricked up the sky a little more....ahhhh maybe not...it''s growing on me while I type :)', '2006-11-01 04:21:30.000000', NULL, 1),
(2981902, 419459, 58567, '<td valign="top">Very evocative....the light effects and tones are suberb!</td>', 'Very evocative....the light effects and tones are suberb!', '2006-11-01 04:22:27.000000', NULL, 1),
(2981909, 419524, 58567, '<td valign="top">Excellent balance and structure...the tones and lighting are very effective...one of my top marks tonight</td>', 'Excellent balance and structure...the tones and lighting are very effective...one of my top marks tonight', '2006-11-01 04:23:39.000000', NULL, 1),
(2981919, 418334, 58567, '<td valign="top">This is reflective in more ways than one and a nice change of pace from the chocolate box autumn pictures which are beginning to grate on me let me tell you!</td>', 'This is reflective in more ways than one and a nice change of pace from the chocolate box autumn pictures which are beginning to grate on me let me tell you!', '2006-11-01 04:28:42.000000', NULL, 1),
(2981923, 420194, 58567, '<td valign="top">Nicely placed leaves...what glue did you use?  Very competent shot</td>', 'Nicely placed leaves...what glue did you use?  Very competent shot', '2006-11-01 04:30:07.000000', NULL, 1),
(2981925, 420748, 58567, '<td valign="top">2 extra points for the deer!</td>', '2 extra points for the deer!', '2006-11-01 04:31:19.000000', NULL, 1),
(2981930, 420072, 58567, '<td valign="top">Everything just right...well done</td>', 'Everything just right...well done', '2006-11-01 04:32:40.000000', NULL, 1),
