(2981934, 418901, 58567, '<td valign="top">Aw shucks...why did they cut down that tree....but you left the stump in on purpose to make a statement..............didn''t you?</td>', 'Aw shucks...why did they cut down that tree....but you left the stump in on purpose to make a statement..............didn''t you?', '2006-11-01 04:34:59.000000', NULL, 1),
(2981936, 418932, 65125, '<td valign="top">Nice colors, maybe a bit too "crowded".</td>', 'Nice colors, maybe a bit too "crowded".', '2006-11-01 04:35:44.000000', NULL, 1),
(2981940, 419525, 58567, '<td valign="top">I can''t see any bares????  Jokes aside..this is well done..I like the juxtaposition of the glowering clouds the island and the swirl of rock.</td>', 'I can''t see any bares????  Jokes aside..this is well done..I like the juxtaposition of the glowering clouds the island and the swirl of rock.', '2006-11-01 04:37:01.000000', NULL, 1),
(2981941, 418382, 58567, '<td valign="top">Evocative and silky</td>', 'Evocative and silky', '2006-11-01 04:37:35.000000', NULL, 1),
(2981944, 420903, 58567, '<td valign="top">Not for the birds...and you...nice</td>', 'Not for the birds...and you...nice', '2006-11-01 04:38:18.000000', NULL, 1),
(2981948, 419029, 65125, '<td valign="top">Interesting. :D</td>', 'Interesting. :D', '2006-11-01 04:38:59.000000', NULL, 1),
(2981950, 418471, 58567, '<td valign="top">Oooh......surreal...Salvidor Dali....very clever...and thankyou for not taking a pic of autumn leaves...if I see another one I''m going to throw up!</td>', 'Oooh......surreal...Salvidor Dali....very clever...and thankyou for not taking a pic of autumn leaves...if I see another one I''m going to throw up!', '2006-11-01 04:39:55.000000', NULL, 1),
