(2981956, 420491, 65125, '<td valign="top">What is the reflection? Also, you could clean your sensor once in a while. :)</td>', 'What is the reflection? Also, you could clean your sensor once in a while. :)', '2006-11-01 04:45:46.000000', NULL, 1),
(2981957, 419459, 65125, '<td valign="top">Nice colors, i like it.</td>', 'Nice colors, i like it.', '2006-11-01 04:46:47.000000', NULL, 1),
(2981964, 417472, 67671, '<td valign="top">well framed shot, looks like a winner to me, well done</td>', 'well framed shot, looks like a winner to me, well done', '2006-11-01 04:51:46.000000', NULL, 1),
(2981967, 419790, 33352, '<td valign="top">3D photography, well done and presented.</td>', '3D photography, well done and presented.', '2006-11-01 04:53:55.000000', NULL, 1),
