(2981977, 418662, 67671, '<td valign="top">too mutch sky</td>', 'too mutch sky', '2006-11-01 04:57:05.000000', NULL, 1),
(2981989, 420107, 67671, '<td valign="top">nice shot, could be framed better, I feel the camera could have been turned a little to the right</td>', 'nice shot, could be framed better, I feel the camera could have been turned a little to the right', '2006-11-01 05:09:32.000000', NULL, 1),
(2981995, 420613, 66878, '<td valign="top">beautiful simetry</td>', 'beautiful simetry', '2006-11-01 05:11:17.000000', NULL, 1),
(2982013, 420214, 31443, '<td valign="top">What a great looking tree there in the middle. I like the composition in this shot very much and the landscape truly amazing...don''t know about the post process,comes out a bit grainy, but then I''m a less is more person..even so like this very much..</td>', 'What a great looking tree there in the middle. I like the composition in this shot very much and the landscape truly amazing...don''t know about the post process,comes out a bit grainy, but then I''m a less is more person..even so like this very much..', '2006-11-01 05:17:09.000000', NULL, 1),
(2982018, 421048, 5354, '<td valign="top">There is only a subtle composition in this image, nothing really striking. The colours are nice but not outstanding. It needs something more, but I''m not sure the subject really has that much potential</td>', 'There is only a subtle composition in this image, nothing really striking. The colours are nice but not outstanding. It needs something more, but I''m not sure the subject really has that much potential', '2006-11-01 05:18:31.000000', NULL, 1),
(2982025, 420187, 5354, '<td valign="top">horizon police will be on your case - keep it straight</td>', 'horizon police will be on your case - keep it straight', '2006-11-01 05:20:01.000000', NULL, 1),
(2982026, 417933, 31443, '<td valign="top">This would have been much nicer with a good dof you''ve managed to have a clear focus only on the foreground leaving the back in too much of a blur..the light seems to have been enough, why not use at least f16 or even smaller apperture?</td>', 'This would have been much nicer with a good dof you''ve managed to have a clear focus only on the foreground leaving the back in too much of a blur..the light seems to have been enough, why not use at least f16 or even smaller apperture?', '2006-11-01 05:20:17.000000', NULL, 1),
(2982031, 420806, 5354, '<td valign="top">If you are going to use the foreground in this way it is disasterous if you don''t keep it in focus. Use a deeper depth of field and a long shutter speed to avoid this problem</td>', 'If you are going to use the foreground in this way it is disasterous if you don''t keep it in focus. Use a deeper depth of field and a long shutter speed to avoid this problem', '2006-11-01 05:21:21.000000', NULL, 1),
(2982034, 420223, 5354, '<td valign="top">The sky is incredible, the foreground is messy and cluttered</td>', 'The sky is incredible, the foreground is messy and cluttered', '2006-11-01 05:21:59.000000', NULL, 1),
(2982036, 419326, 5354, '<td valign="top">Beautiful if a little dark</td>', 'Beautiful if a little dark', '2006-11-01 05:22:17.000000', NULL, 1),
(2982043, 420455, 5354, '<td valign="top">Why waste over half of your frame on such a bland sky. The few whiss of cloud don''t really have sufficient weight to hold that together</td>', 'Why waste over half of your frame on such a bland sky. The few whiss of cloud don''t really have sufficient weight to hold that together', '2006-11-01 05:23:27.000000', NULL, 1),
(2982047, 418487, 58567, '<td valign="top">Great pic...no bloody autumn leaves, good! superbly framed and processed....9</td>', 'Great pic...no bloody autumn leaves, good! superbly framed and processed....9', '2006-11-01 05:24:14.000000', NULL, 1),
(2982048, 420908, 31443, '<td valign="top">Well done WB just wish there was one little spot to compare the size of this area, I''m sure its huge, don''t ever go so far on that ledge again!!!</td>', 'Well done WB just wish there was one little spot to compare the size of this area, I''m sure its huge, don''t ever go so far on that ledge again!!!', '2006-11-01 05:24:23.000000', NULL, 1),
