(2982078, 420650, 5354, '<td valign="top">Very nice, I wonder if it would be stronger just zoomed in a little more</td>', 'Very nice, I wonder if it would be stronger just zoomed in a little more', '2006-11-01 05:31:47.000000', NULL, 1),
(2982081, 417729, 5354, '<td valign="top">Landscape ?</td>', 'Landscape ?', '2006-11-01 05:32:15.000000', NULL, 1),
