(2982884, 418910, 31443, '<td valign="top">Hey swans, come a little closer! Lovely setup, you should have brought a few slices of bread with you ;)</td>', 'Hey swans, come a little closer! Lovely setup, you should have brought a few slices of bread with you ;)', '2006-11-01 09:29:06.000000', NULL, 1),
(2982887, 421016, 67152, '<td valign="top">What a waterfall!</td>', 'What a waterfall!', '2006-11-01 09:29:26.000000', NULL, 1),
(2982893, 418910, 66923, '<td valign="top">nice clean shot</td>', 'nice clean shot', '2006-11-01 09:30:22.000000', NULL, 1),
(2982895, 419997, 66923, '<td valign="top">beautiful tones!</td>', 'beautiful tones!', '2006-11-01 09:30:57.000000', NULL, 1),
(2982896, 418944, 64175, '<td valign="top">The shot comes off a little flat to me.  I''m not sure if the nature conditions would give it, but it just needs some more depth in the middle to feel like it is carrying me there.  The tire tracks stop a little short to do that.  5.</td>', 'The shot comes off a little flat to me.  I''m not sure if the nature conditions would give it, but it just needs some more depth in the middle to feel like it is carrying me there.  The tire tracks stop a little short to do that.  5.', '2006-11-01 09:30:58.000000', NULL, 1),
(2982898, 421055, 66384, '<td valign="top">The lines of the fence, yellow flowers, and mountains are all running horizontally. I think this would be better taken in the landscape orientation,</td>', 'The lines of the fence, yellow flowers, and mountains are all running horizontally. I think this would be better taken in the landscape orientation,', '2006-11-01 09:31:20.000000', NULL, 1),
(2982902, 418378, 66923, '<td valign="top">great background! and the man passing by makes the shot! great!!!</td>', 'great background! and the man passing by makes the shot! great!!!', '2006-11-01 09:31:46.000000', NULL, 1),
(2982907, 419453, 66384, '<td valign="top">It doesn''t effect my rating, but why so small? I''d like to be able to see al little more detail. Nice composition</td>', 'It doesn''t effect my rating, but why so small? I''d like to be able to see al little more detail. Nice composition', '2006-11-01 09:33:18.000000', NULL, 1),
(2982909, 420072, 64175, '<td valign="top">This one would do very well in the reflective challenge that was just released too.  This is a very nice shot.  Well done.  I love the yellow folliage.  I''m not crazy about the Depth of field on the redish leaves as the come off blurry (as they would if focus is on the yellow) but they are such a rich color that my eye is taken to them as another strong subject but finds them out of focus which is slightly disappointing.  Overall score: 8</td>', 'This one would do very well in the reflective challenge that was just released too.  This is a very nice shot.  Well done.  I love the yellow folliage.  I''m not crazy about the Depth of field on the redish leaves as the come off blurry (as they would if focus is on the yellow) but they are such a rich color that my eye is taken to them as another strong subject but finds them out of focus which is slightly disappointing.  Overall score: 8', '2006-11-01 09:33:29.000000', NULL, 1),
(2982912, 420564, 67899, '<td valign="top">This photo caught my eye... really nice color.</td>', 'This photo caught my eye... really nice color.', '2006-11-01 09:33:35.000000', NULL, 1),
(2982914, 419524, 67899, '<td valign="top">Nice composition</td>', 'Nice composition', '2006-11-01 09:33:57.000000', NULL, 1),
(2982915, 420563, 31443, '<td valign="top">The bright sunshine didn''t do this image any favors...what a fantastic landscape, the goes from side to side weaving up to the top. I always have problems trying to regulate the light, it''s hard to post process when the sky looks so burnt but darkening the overall image would probably do wonders..anyway, like this alot, it''s beautiful</td>', 'The bright sunshine didn''t do this image any favors...what a fantastic landscape, the goes from side to side weaving up to the top. I always have problems trying to regulate the light, it''s hard to post process when the sky looks so burnt but darkening the overall image would probably do wonders..anyway, like this alot, it''s beautiful', '2006-11-01 09:34:06.000000', NULL, 1),
(2982918, 419885, 66384, '<td valign="top">Very nice.</td>', 'Very nice.', '2006-11-01 09:34:42.000000', NULL, 1),
(2982922, 418655, 67152, '<td valign="top">The composition and framing of the photo is very nice - but the green colors are too vibrant for the rest of the photo.  If the rocks were more dramatically colored, I think the green would have worked for me.</td>', 'The composition and framing of the photo is very nice - but the green colors are too vibrant for the rest of the photo.  If the rocks were more dramatically colored, I think the green would have worked for me.', '2006-11-01 09:35:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2982926, 418297, 64175, '<td valign="top">I like the unique crop, not sure if others will.  This is definitely a landscape in portrait per the challenge, but the subject matter doesn''t really have enough color contrast to draw my eye to anything in particular.  I think it may have been just a little too late in the season so this composition missed some possible good colors in the trees. Of course that too would have been out of the submission timeline.  I just think the composition needs a little work.  Score: 5.</td>', 'I like the unique crop, not sure if others will.  This is definitely a landscape in portrait per the challenge, but the subject matter doesn''t really have enough color contrast to draw my eye to anything in particular.  I think it may have been just a little too late in the season so this composition missed some possible good colors in the trees. Of course that too would have been out of the submission timeline.  I just think the composition needs a little work.  Score: 5.', '2006-11-01 09:35:31.000000', NULL, 1),
(2982929, 420536, 64175, '<td valign="top">As a viewer, I would have preferred to see the opposite of this where the beautiful folliage was in focus and the foreground was out of focus as a silohuette.</td>', 'As a viewer, I would have preferred to see the opposite of this where the beautiful folliage was in focus and the foreground was out of focus as a silohuette.', '2006-11-01 09:36:37.000000', NULL, 1),
(2982933, 420813, 14515, '<td valign="top">love the colors in this shot!</td>', 'love the colors in this shot!', '2006-11-01 09:37:20.000000', NULL, 1),
(2982934, 419336, 66384, '<td valign="top">Somehow, I want to see more of the right and left of this scene. Perhaps it is the horizontal white line on the cliff leading me to the sides. It might have been better in the landscape orientation. Still it is a very nice photo.</td>', 'Somehow, I want to see more of the right and left of this scene. Perhaps it is the horizontal white line on the cliff leading me to the sides. It might have been better in the landscape orientation. Still it is a very nice photo.', '2006-11-01 09:37:30.000000', NULL, 1),
(2982936, 418310, 14515, '<td valign="top">almost looks like there is a skull in the water.</td>', 'almost looks like there is a skull in the water.', '2006-11-01 09:38:00.000000', NULL, 1),
(2982946, 418971, 66384, '<td valign="top">Nice simplicity and beautiful color.</td>', 'Nice simplicity and beautiful color.', '2006-11-01 09:39:01.000000', NULL, 1),
(2982948, 419937, 14515, '<td valign="top">interesting shot, but its hard to find a subject. maybe try selective focusing</td>', 'interesting shot, but its hard to find a subject. maybe try selective focusing', '2006-11-01 09:39:33.000000', NULL, 1),
(2982949, 418904, 64175, '<td valign="top">I like the composition a lot but not the angle of the shot. I feel like I''m falling to the left to try to see the photo. It has dramatic effect, but it takes away from the image.</td>', 'I like the composition a lot but not the angle of the shot. I feel like I''m falling to the left to try to see the photo. It has dramatic effect, but it takes away from the image.', '2006-11-01 09:39:35.000000', NULL, 1),
(2982955, 421048, 64175, '<td valign="top">The saturation on the greens is good, but I would like a bit more vibrant colors in the yellows/oranges.  They come off a little flat against the vivid greens.  Score: 6.</td>', 'The saturation on the greens is good, but I would like a bit more vibrant colors in the yellows/oranges.  They come off a little flat against the vivid greens.  Score: 6.', '2006-11-01 09:40:48.000000', NULL, 1),
(2982956, 419544, 66384, '<td valign="top">The shallow DOF bothers me in this shot. I eye goes right to the mountains, and I can''t see them clearly.</td>', 'The shallow DOF bothers me in this shot. I eye goes right to the mountains, and I can''t see them clearly.', '2006-11-01 09:40:49.000000', NULL, 1),
(2982963, 420685, 64175, '<td valign="top">The post processing elements on this one appear to be a bit too strong. The skyline comes off a bit "fake" and the edge of the top of the trees looks oversharpened.</td>', 'The post processing elements on this one appear to be a bit too strong. The skyline comes off a bit "fake" and the edge of the top of the trees looks oversharpened.', '2006-11-01 09:42:48.000000', NULL, 1),
(2982971, 420952, 66384, '<td valign="top">Very pretty and nice composition. The white "scratch" in the sky is distracting for me, and I would have cloned it out.</td>', 'Very pretty and nice composition. The white "scratch" in the sky is distracting for me, and I would have cloned it out.', '2006-11-01 09:44:18.000000', NULL, 1),
(2982983, 419848, 66384, '<td valign="top">Very moody, nice lighting and color, and nice use of the portrait orientation.</td>', 'Very moody, nice lighting and color, and nice use of the portrait orientation.', '2006-11-01 09:46:15.000000', NULL, 1),
(2982991, 420693, 66384, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2006-11-01 09:47:18.000000', NULL, 1),
(2983004, 420684, 66384, '<td valign="top">Wonderful shot! Beautiful color tones, lines, and textures.</td>', 'Wonderful shot! Beautiful color tones, lines, and textures.', '2006-11-01 09:51:21.000000', NULL, 1),
(2983014, 419029, 64175, '<td valign="top">Not sure if it was intentional, but you appear to have placed this in landscape format rather than in portrait format.</td>', 'Not sure if it was intentional, but you appear to have placed this in landscape format rather than in portrait format.', '2006-11-01 09:53:09.000000', NULL, 1),
(2983017, 420401, 64175, '<td valign="top">Images seem a bit oversaturated, but I do like the composition. 6.</td>', 'Images seem a bit oversaturated, but I do like the composition. 6.', '2006-11-01 09:53:48.000000', NULL, 1),
(2983023, 420598, 66384, '<td valign="top">What a great variety of stones, bricks, and pavers. So many colors and textures. And I do want to know what''s behind that door. Nice shot!</td>', 'What a great variety of stones, bricks, and pavers. So many colors and textures. And I do want to know what''s behind that door. Nice shot!', '2006-11-01 09:54:58.000000', NULL, 1),
(2983027, 420185, 64175, '<td valign="top">I''m sorry, but this is a DNMC (did not meet challenge) entry. The challenge is looking for a Landscape that was shot vertically. I would think that you meant to submit this in challenge for Portrait In Landscape Format.  So, it gets a 1 do to DNMC, but it is a cute photo of the girl.</td>', 'I''m sorry, but this is a DNMC (did not meet challenge) entry. The challenge is looking for a Landscape that was shot vertically. I would think that you meant to submit this in challenge for Portrait In Landscape Format.  So, it gets a 1 do to DNMC, but it is a cute photo of the girl.', '2006-11-01 09:55:07.000000', NULL, 1),
(2983042, 418655, 64175, '<td valign="top">I''m not a fan of the bright green border. It pulls my eyes to either side rather than has me focusing on the picture.  I don''t like to count off much though for choice of borders as I too have gone with colored ones that have not been found favorable. The image is very nice. I find the greens on the bottom third of the photo to be a little over saturated.  Score: 6.</td>', 'I''m not a fan of the bright green border. It pulls my eyes to either side rather than has me focusing on the picture.  I don''t like to count off much though for choice of borders as I too have gone with colored ones that have not been found favorable. The image is very nice. I find the greens on the bottom third of the photo to be a little over saturated.  Score: 6.', '2006-11-01 09:57:06.000000', NULL, 1),
(2983044, 420605, 64175, '<td valign="top">Image comes off as out of focus. Pretty sky colors though. 5.</td>', 'Image comes off as out of focus. Pretty sky colors though. 5.', '2006-11-01 09:57:38.000000', NULL, 1),
(2983051, 419109, 64175, '<td valign="top">I''d give more points if this were in the bokeh challenge, but the subject (grass/wheat) is just not strong enough to carry the photo.  5.</td>', 'I''d give more points if this were in the bokeh challenge, but the subject (grass/wheat) is just not strong enough to carry the photo.  5.', '2006-11-01 09:58:35.000000', NULL, 1),
(2983059, 421040, 12093, '<td valign="top">I wish the cell phone wasn''t in the pic.</td>', 'I wish the cell phone wasn''t in the pic.', '2006-11-01 09:59:41.000000', NULL, 1),
(2983061, 420970, 66384, '<td valign="top">Very beautiful!!</td>', 'Very beautiful!!', '2006-11-01 10:00:29.000000', NULL, 1),
(2983076, 419289, 64175, '<td valign="top">The colors are too over saturated for my taste. 5.</td>', 'The colors are too over saturated for my taste. 5.', '2006-11-01 10:03:29.000000', NULL, 1),
(2983080, 420962, 66384, '<td valign="top">Nice use of portrait orientation. I like the composition - the rock in the forground balances the lighthouse nicely. Also lovely lighting. Seems to be a lot of negative space in the upper left.</td>', 'Nice use of portrait orientation. I like the composition - the rock in the forground balances the lighthouse nicely. Also lovely lighting. Seems to be a lot of negative space in the upper left.', '2006-11-01 10:04:19.000000', NULL, 1),
(2983081, 419337, 67258, '<td valign="top">You have captured the light on the grass well, but whilst I do tend to like simple minimalistic photos, the composition of this does seem a little dull.</td>', 'You have captured the light on the grass well, but whilst I do tend to like simple minimalistic photos, the composition of this does seem a little dull.', '2006-11-01 10:04:44.000000', NULL, 1),
(2983083, 419203, 67258, '<td valign="top">Interesting lighting - curious to know how this effect was achieved.</td>', 'Interesting lighting - curious to know how this effect was achieved.', '2006-11-01 10:05:33.000000', NULL, 1),
(2983113, 419383, 58609, '<td valign="top">love the lens... good picture :o)</td>', 'love the lens... good picture :o)', '2006-11-01 10:10:23.000000', NULL, 1),
(2983138, 418297, 66384, '<td valign="top">Awful lot of grass and not much tree</td>', 'Awful lot of grass and not much tree', '2006-11-01 10:13:43.000000', NULL, 1),
(2983139, 417472, 65858, '<td valign="top">Wow - great night shot!  The only thing I can comment on is that I might have liked to see the background (non-bridge elements) a little darker to make the bridge stand out a bit more.  Still, excellent!</td>', 'Wow - great night shot!  The only thing I can comment on is that I might have liked to see the background (non-bridge elements) a little darker to make the bridge stand out a bit more.  Still, excellent!', '2006-11-01 10:13:47.000000', NULL, 1),
(2983145, 420642, 30508, '<td valign="top">I like the composition but the colors seem to be a little flat.  A little more brightness and contrast could help.</td>', 'I like the composition but the colors seem to be a little flat.  A little more brightness and contrast could help.', '2006-11-01 10:14:18.000000', NULL, 1),
(2983154, 417345, 30508, '<td valign="top">Gorgeous colors and composition.  There is a little bit of noise (perhaps from bumping the saturation?).  Overall, though, you''ve captured the rustic autumn feel of this nicely.</td>', 'Gorgeous colors and composition.  There is a little bit of noise (perhaps from bumping the saturation?).  Overall, though, you''ve captured the rustic autumn feel of this nicely.', '2006-11-01 10:15:32.000000', NULL, 1),
(2983165, 420126, 30508, '<td valign="top">Great lines and shadows.  It feels just a little bit off balance because there isn''t much on the right side of the frame to counter the tree, but the hills do help with that a little.  Still a wonderful shot, though.</td>', 'Great lines and shadows.  It feels just a little bit off balance because there isn''t much on the right side of the frame to counter the tree, but the hills do help with that a little.  Still a wonderful shot, though.', '2006-11-01 10:16:52.000000', NULL, 1),
(2983171, 418655, 66384, '<td valign="top">Nice color, nice use of the portrait orientation, good composition. I like it a lot.</td>', 'Nice color, nice use of the portrait orientation, good composition. I like it a lot.', '2006-11-01 10:17:56.000000', NULL, 1),
(2983193, 420063, 66384, '<td valign="top">Very pretty photo. Nice quality of light. I like the way the white water curves around the rock.</td>', 'Very pretty photo. Nice quality of light. I like the way the white water curves around the rock.', '2006-11-01 10:21:49.000000', NULL, 1),
(2983199, 419937, 30508, '<td valign="top">Nice lines and shapes.  I''d like to see this with a little more light in the foreground though.</td>', 'Nice lines and shapes.  I''d like to see this with a little more light in the foreground though.', '2006-11-01 10:22:29.000000', NULL, 1),
(2983201, 420194, 64175, '<td valign="top">I like this shot a lot. Wonderful color contrasts on the yellows and greens, nice lighting in the background.  I think I would have preferred a faster shutter as I''m not a huge fan of the long shutters on water giving the foamy look.  9.</td>', 'I like this shot a lot. Wonderful color contrasts on the yellows and greens, nice lighting in the background.  I think I would have preferred a faster shutter as I''m not a huge fan of the long shutters on water giving the foamy look.  9.', '2006-11-01 10:22:46.000000', NULL, 1),
(2983213, 419660, 30508, '<td valign="top">I like the idea you are going for with the noise, but I find the color cast a little distracting.  Also, the foreground doesn''t really add much for me.  I might have liked it more if you had tilted your lense up a little more.</td>', 'I like the idea you are going for with the noise, but I find the color cast a little distracting.  Also, the foreground doesn''t really add much for me.  I might have liked it more if you had tilted your lense up a little more.', '2006-11-01 10:24:29.000000', NULL, 1),
(2983215, 419847, 64175, '<td valign="top">I''m not normally of fan of long shutters on water but I do like the way it works in this one.  10.  Nice job.</td>', 'I''m not normally of fan of long shutters on water but I do like the way it works in this one.  10.  Nice job.', '2006-11-01 10:25:35.000000', NULL, 1),
(2983224, 417693, 59148, '<td valign="top">Photo is less desirable with the power lines in it.</td>', 'Photo is less desirable with the power lines in it.', '2006-11-01 10:28:19.000000', NULL, 1),
(2983231, 418656, 66384, '<td valign="top">A little flat. I don''t feel the distance between the flowers and the waterfall. Nice place though - worth trying more shots at different times of day.</td>', 'A little flat. I don''t feel the distance between the flowers and the waterfall. Nice place though - worth trying more shots at different times of day.', '2006-11-01 10:29:07.000000', NULL, 1),
(2983235, 419948, 64175, '<td valign="top">You have likely gotten a number of these, but I believe this was entered in the wrong challenge and thus is a DNMC entry which generates a score of 1.  If it had been entered in the portrait in landscape challenge, it would probably be a 5 IMO.  The bokeh is very nice in the back, but the yellowed highlights on the right side of the image are a bit blown out (over exposed).<br/> <br/>I''m sure the subject means a lot to you and that is what is important. Photography is so subjective and on portraits, we generally film those that move us. It is hard for someone who knows nothing of the subject to make that connection so it becomes very important that the technical aspects of the photo are right on.  I have a lot of post-processing learning ahead of me so please just treat these comments as merely one viewers opinion.</td>', 'You have likely gotten a number of these, but I believe this was entered in the wrong challenge and thus is a DNMC entry which generates a score of 1.  If it had been entered in the portrait in landscape challenge, it would probably be a 5 IMO.  The bokeh is very nice in the back, but the yellowed highlights on the right side of the image are a bit blown out (over exposed). I''m sure the subject means a lot to you and that is what is important. Photography is so subjective and on portraits, we generally film those that move us. It is hard for someone who knows nothing of the subject to make that connection so it becomes very important that the technical aspects of the photo are right on.  I have a lot of post-processing learning ahead of me so please just treat these comments as merely one viewers opinion.', '2006-11-01 10:29:52.000000', NULL, 1),
(2983237, 420199, 30508, '<td valign="top">Nice colors and composition.  Joshua trees make great subjects.  For my taste, taking a half step to the left or right so that the plant is not centered would have improved the composition a little.  Also, the horizon feels a little tilted.</td>', 'Nice colors and composition.  Joshua trees make great subjects.  For my taste, taking a half step to the left or right so that the plant is not centered would have improved the composition a little.  Also, the horizon feels a little tilted.', '2006-11-01 10:30:17.000000', NULL, 1),
(2983239, 420187, 59148, '<td valign="top">tower in the photo draws away from the quality</td>', 'tower in the photo draws away from the quality', '2006-11-01 10:30:23.000000', NULL, 1),
(2983244, 420961, 59148, '<td valign="top">Too dark for my taste with not much going in in the photo.</td>', 'Too dark for my taste with not much going in in the photo.', '2006-11-01 10:31:18.000000', NULL, 1),
(2983247, 417562, 59148, '<td valign="top">Good tonal range</td>', 'Good tonal range', '2006-11-01 10:31:59.000000', NULL, 1),
(2983248, 420844, 66384, '<td valign="top">The color and contrast have been cranked up a little too much for my taste. Still is it a very nice shot.</td>', 'The color and contrast have been cranked up a little too much for my taste. Still is it a very nice shot.', '2006-11-01 10:32:10.000000', NULL, 1),
(2983252, 417361, 59148, '<td valign="top">like the lower part of the photo better with a different crop</td>', 'like the lower part of the photo better with a different crop', '2006-11-01 10:32:46.000000', NULL, 1),
(2983254, 419294, 59148, '<td valign="top">Not very sharp not sure of the intent but photo would have been better if it was tac sharp</td>', 'Not very sharp not sure of the intent but photo would have been better if it was tac sharp', '2006-11-01 10:33:30.000000', NULL, 1),
(2983261, 420915, 59148, '<td valign="top">photo too dark kills the reflection on the water</td>', 'photo too dark kills the reflection on the water', '2006-11-01 10:34:36.000000', NULL, 1),
(2983266, 418064, 59148, '<td valign="top">Tired of the infared look like the tomb stones</td>', 'Tired of the infared look like the tomb stones', '2006-11-01 10:35:34.000000', NULL, 1),
(2983267, 421007, 64175, '<td valign="top">Border is just a bit too thick IMO, but I don''t count off for that. Nice image. 9.</td>', 'Border is just a bit too thick IMO, but I don''t count off for that. Nice image. 9.', '2006-11-01 10:35:38.000000', NULL, 1),
(2983275, 420536, 59148, '<td valign="top">Too dark</td>', 'Too dark', '2006-11-01 10:37:12.000000', NULL, 1),
(2983279, 419118, 59148, '<td valign="top">Not sure if this meets the challenge but nice photo</td>', 'Not sure if this meets the challenge but nice photo', '2006-11-01 10:38:09.000000', NULL, 1),
(2983281, 421016, 66384, '<td valign="top">I love this shot. I would like it even better if it were rotated slightly clockwise so the trees were straight.</td>', 'I love this shot. I would like it even better if it were rotated slightly clockwise so the trees were straight.', '2006-11-01 10:38:25.000000', NULL, 1),
(2983303, 418297, 30508, '<td valign="top">This is a nice, peaceful composition, but as such comes across as missing a little zing.  The foreground really just doesn''t have much to hold the viewer''s interest.</td>', 'This is a nice, peaceful composition, but as such comes across as missing a little zing.  The foreground really just doesn''t have much to hold the viewer''s interest.', '2006-11-01 10:42:07.000000', NULL, 1),
(2983306, 419029, 59148, '<td valign="top">Is this intentional or is your photo just turned the wrong way</td>', 'Is this intentional or is your photo just turned the wrong way', '2006-11-01 10:42:19.000000', NULL, 1),
(2983309, 417490, 66384, '<td valign="top">This is beautiful. I wish I could see just a little more into the woods.</td>', 'This is beautiful. I wish I could see just a little more into the woods.', '2006-11-01 10:42:40.000000', NULL, 1),
(2983310, 420029, 16488, '<td valign="top">Love the colors and the quiet feel in this image. I''d like it even more if there were crisp focus on the ship.</td>', 'Love the colors and the quiet feel in this image. I''d like it even more if there were crisp focus on the ship.', '2006-11-01 10:43:05.000000', NULL, 1),
(2983315, 420962, 30508, '<td valign="top">Very nicely done.  This would be top-notch if the sky were a little more vibrant and if there was just a little more light on the rocks.  Still, a superb shot.</td>', 'Very nicely done.  This would be top-notch if the sky were a little more vibrant and if there was just a little more light on the rocks.  Still, a superb shot.', '2006-11-01 10:43:45.000000', NULL, 1),
(2983322, 418948, 66384, '<td valign="top">Nice curves, nice use of the portrait orientation. The color of the sky bothers me. Still I like the shot.</td>', 'Nice curves, nice use of the portrait orientation. The color of the sky bothers me. Still I like the shot.', '2006-11-01 10:44:54.000000', NULL, 1),
(2983324, 419294, 30508, '<td valign="top">Your composition and colors are great.  Unfortunately it looks a little blurry.  I''m guessing you hand-held this and given the long shutter speed, you got some camera shake.  Try this again with either a tripod or some other way of supporting the camera and you would have a very good shot.</td>', 'Your composition and colors are great.  Unfortunately it looks a little blurry.  I''m guessing you hand-held this and given the long shutter speed, you got some camera shake.  Try this again with either a tripod or some other way of supporting the camera and you would have a very good shot.', '2006-11-01 10:45:14.000000', NULL, 1),
(2983332, 418445, 16488, '<td valign="top">The light feels very flat...the perspective is there, but the depth is not.</td>', 'The light feels very flat...the perspective is there, but the depth is not.', '2006-11-01 10:45:49.000000', NULL, 1),
(2983337, 419525, 66384, '<td valign="top">Very nice!</td>', 'Very nice!', '2006-11-01 10:46:57.000000', NULL, 1),
(2983344, 419993, 16488, '<td valign="top">Seems like the colors could use a little more saturation and the image as a whole a bit of sharpening. The composition is alright but the light puts the emphasis on the sky and tree tops while the person and the stream compete to be the subject. (Would also have cropped in from the left to eliminate the car.)</td>', 'Seems like the colors could use a little more saturation and the image as a whole a bit of sharpening. The composition is alright but the light puts the emphasis on the sky and tree tops while the person and the stream compete to be the subject. (Would also have cropped in from the left to eliminate the car.)', '2006-11-01 10:48:25.000000', NULL, 1),
(2983349, 420005, 30508, '<td valign="top">Nice autumn colors.  The foreground is a bit too dark, though.  A graduated ND filter would help compensate for that.</td>', 'Nice autumn colors.  The foreground is a bit too dark, though.  A graduated ND filter would help compensate for that.', '2006-11-01 10:49:07.000000', NULL, 1),
(2983352, 419326, 16488, '<td valign="top">Beautiful falls and long exposure. The light of the sky, however, takes attention away from the subject and seems unnecessary.</td>', 'Beautiful falls and long exposure. The light of the sky, however, takes attention away from the subject and seems unnecessary.', '2006-11-01 10:49:59.000000', NULL, 1),
(2983360, 421038, 30508, '<td valign="top">Nice sharp sillouhettes against a beautiful sky.  There''s a little bit of noise in the sky, perhaps from bumping the saturation a little too much, but that''s just a nit.</td>', 'Nice sharp sillouhettes against a beautiful sky.  There''s a little bit of noise in the sky, perhaps from bumping the saturation a little too much, but that''s just a nit.', '2006-11-01 10:50:34.000000', NULL, 1),
(2983363, 418936, 16488, '<td valign="top">Pretty landscape but it just fights to be in landscape view with all those horizontals from the clouds on down.</td>', 'Pretty landscape but it just fights to be in landscape view with all those horizontals from the clouds on down.', '2006-11-01 10:50:58.000000', NULL, 1),
(2983386, 421042, 66384, '<td valign="top">Beautiful colors. Nice shot. I''d clone out the road sign. It breaks the nice curved line of the road and is a bit distracting.</td>', 'Beautiful colors. Nice shot. I''d clone out the road sign. It breaks the nice curved line of the road and is a bit distracting.', '2006-11-01 10:53:29.000000', NULL, 1),
(2983389, 420831, 16488, '<td valign="top">I find it disturbing that the tower is tilting. Otherwise, the direction of the light and the interesting sky help energize a much-done subject.</td>', 'I find it disturbing that the tower is tilting. Otherwise, the direction of the light and the interesting sky help energize a much-done subject.', '2006-11-01 10:53:36.000000', NULL, 1),
(2983393, 421005, 30508, '<td valign="top">Nice sunset colors and use of leading lines in the road.  I think this could really pop if the foreground were brighter (perhaps by shooting in raw and then converting using different settings for foreground and background and then combining in post process) and the horizon were moved up in the frame to reduce the amount of empty sky.</td>', 'Nice sunset colors and use of leading lines in the road.  I think this could really pop if the foreground were brighter (perhaps by shooting in raw and then converting using different settings for foreground and background and then combining in post process) and the horizon were moved up in the frame to reduce the amount of empty sky.', '2006-11-01 10:53:54.000000', NULL, 1),
(2983402, 418992, 64929, '<td valign="top">Perfect reflection - very nice capture!</td>', 'Perfect reflection - very nice capture!', '2006-11-01 10:54:52.000000', NULL, 1),
(2983414, 419937, 64929, '<td valign="top">This shot would have had more ''pop'' in color IMHO</td>', 'This shot would have had more ''pop'' in color IMHO', '2006-11-01 10:55:56.000000', NULL, 1),
(2983415, 419149, 16488, '<td valign="top">The first thing I notice is the telephone wires...not a good thing. Despite the lovely clouds the lighting in the rest of the image is rather flat...it lacks dimension. The subject is there, the image is not.</td>', 'The first thing I notice is the telephone wires...not a good thing. Despite the lovely clouds the lighting in the rest of the image is rather flat...it lacks dimension. The subject is there, the image is not.', '2006-11-01 10:56:15.000000', NULL, 1),
(2983416, 420509, 66384, '<td valign="top">Not my idea of a landscape, but lovely colors, texture, and light.</td>', 'Not my idea of a landscape, but lovely colors, texture, and light.', '2006-11-01 10:56:19.000000', NULL, 1),
