(2985076, 420545, 58567, '<td valign="top">Very nice...good reflection and mood...perhaps a little overprocessed with the aqua?</td>', 'Very nice...good reflection and mood...perhaps a little overprocessed with the aqua?', '2006-11-01 15:32:33.000000', NULL, 1),
(2985078, 420491, 59148, '<td valign="top">photo appears to be shot from inside a vehicle some kind of glare on the lens or window plus power lines also on the small size</td>', 'photo appears to be shot from inside a vehicle some kind of glare on the lens or window plus power lines also on the small size', '2006-11-01 15:33:06.000000', NULL, 1),
(2985084, 419660, 64175, '<td valign="top">I''m not a big fan of adding noise to a photo, but this composition pulls it off well.  Good job. 8.</td>', 'I''m not a big fan of adding noise to a photo, but this composition pulls it off well.  Good job. 8.', '2006-11-01 15:33:32.000000', NULL, 1),
(2985087, 417083, 58567, '<td valign="top">Good angles...would have been better if you had enlarged your upload</td>', 'Good angles...would have been better if you had enlarged your upload', '2006-11-01 15:33:42.000000', NULL, 1),
