(2985090, 420800, 58567, '<td valign="top">Cleverly processed</td>', 'Cleverly processed', '2006-11-01 15:34:18.000000', NULL, 1),
(2985092, 420706, 59148, '<td valign="top">Over saturated.. Wish colors would have been more natural</td>', 'Over saturated.. Wish colors would have been more natural', '2006-11-01 15:34:25.000000', NULL, 1),
(2985101, 419055, 58567, '<td valign="top">Very evocative..great textures</td>', 'Very evocative..great textures', '2006-11-01 15:35:11.000000', NULL, 1),
(2985109, 419383, 58567, '<td valign="top">Clever fisheye...gets another point for innovation</td>', 'Clever fisheye...gets another point for innovation', '2006-11-01 15:35:57.000000', NULL, 1),
(2985112, 417445, 30508, '<td valign="top">Well, this certainly isn''t in portrait orientation, which is sad because you have a very dramatic subject here and the falls would lend themselves nicely to the portrait orientation.  Also, the size of the image is too small.</td>', 'Well, this certainly isn''t in portrait orientation, which is sad because you have a very dramatic subject here and the falls would lend themselves nicely to the portrait orientation.  Also, the size of the image is too small.', '2006-11-01 15:36:09.000000', NULL, 1),
(2985115, 419287, 58567, '<td valign="top">Got an extra point for the title</td>', 'Got an extra point for the title', '2006-11-01 15:36:34.000000', NULL, 1),
(2985120, 420214, 30508, '<td valign="top">Nice colors and composition.  I really like the lone tall tree agains the dramatic sky.  This does seem quite oversharpened though.</td>', 'Nice colors and composition.  I really like the lone tall tree agains the dramatic sky.  This does seem quite oversharpened though.', '2006-11-01 15:36:58.000000', NULL, 1),
(2985122, 420908, 58567, '<td valign="top">Spectacular shot, nicely handled</td>', 'Spectacular shot, nicely handled', '2006-11-01 15:37:08.000000', NULL, 1),
(2985126, 418370, 30508, '<td valign="top">Very nice perspective.</td>', 'Very nice perspective.', '2006-11-01 15:37:44.000000', NULL, 1),
(2985131, 417722, 30508, '<td valign="top">I like how the road leads the eye in to the tower as well as the framing.</td>', 'I like how the road leads the eye in to the tower as well as the framing.', '2006-11-01 15:38:22.000000', NULL, 1),
(2985135, 419937, 58567, '<td valign="top">Nicely constructed and the desaturation works....so good to see something that isn''t icky, chocolate box Fall/Autumn leaves :)</td>', 'Nicely constructed and the desaturation works....so good to see something that isn''t icky, chocolate box Fall/Autumn leaves :)', '2006-11-01 15:38:31.000000', NULL, 1),
(2985144, 420935, 30508, '<td valign="top">Nice autumn colors.  I like the composition of this with the portico in the lower left balanced by the trees reaching into the sky.</td>', 'Nice autumn colors.  I like the composition of this with the portico in the lower left balanced by the trees reaching into the sky.', '2006-11-01 15:39:09.000000', NULL, 1),
(2985150, 420499, 58567, '<td valign="top">Nice bit of countryside...well spotted and processed</td>', 'Nice bit of countryside...well spotted and processed', '2006-11-01 15:39:52.000000', NULL, 1),
(2985154, 418841, 30508, '<td valign="top">This would be much better if you''d used the full 640 pixels in height.  As it is, it''s a nice composition, but maybe just a tad bit too dark.</td>', 'This would be much better if you''d used the full 640 pixels in height.  As it is, it''s a nice composition, but maybe just a tad bit too dark.', '2006-11-01 15:40:07.000000', NULL, 1),
(2985165, 420401, 30508, '<td valign="top">Brilliant colors (maybe a little too saturated).  Too bad the river is so brown.</td>', 'Brilliant colors (maybe a little too saturated).  Too bad the river is so brown.', '2006-11-01 15:41:03.000000', NULL, 1),
(2985168, 420803, 58567, '<td valign="top">Simple and effective</td>', 'Simple and effective', '2006-11-01 15:41:21.000000', NULL, 1),
(2985179, 418345, 30508, '<td valign="top">Nicely composed.  I really like the colors in the sky and the reflection on the water.  I wish there was more detail or interest in the foreground though.</td>', 'Nicely composed.  I really like the colors in the sky and the reflection on the water.  I wish there was more detail or interest in the foreground though.', '2006-11-01 15:42:21.000000', NULL, 1),
(2985183, 418454, 58567, '<td valign="top">Chocolate box pretty....you certainly picked your spot well...good colour combinations and of course, the reflection</td>', 'Chocolate box pretty....you certainly picked your spot well...good colour combinations and of course, the reflection', '2006-11-01 15:42:46.000000', NULL, 1),
(2985187, 420413, 30508, '<td valign="top">Beautiful.  I love the sky, the reflections, the colors, and most of all the mist in the background.</td>', 'Beautiful.  I love the sky, the reflections, the colors, and most of all the mist in the background.', '2006-11-01 15:42:54.000000', NULL, 1),
(2985194, 417629, 30508, '<td valign="top">I like the colors in the background, but the foreground is a little too dark and disinteresting.</td>', 'I like the colors in the background, but the foreground is a little too dark and disinteresting.', '2006-11-01 15:43:46.000000', NULL, 1),
(2985200, 421093, 58567, '<td valign="top">Yes....would have done well in the oxymoron comp.  Does well here too</td>', 'Yes....would have done well in the oxymoron comp.  Does well here too', '2006-11-01 15:44:16.000000', NULL, 1),
(2985205, 419874, 30508, '<td valign="top">Interesting composition.  To bad it''s so hazy out toward the island.</td>', 'Interesting composition.  To bad it''s so hazy out toward the island.', '2006-11-01 15:44:42.000000', NULL, 1),
(2985208, 421087, 30508, '<td valign="top">Wow, very dramatic sky.  Looks a little pixelated though.  Was this enlarged from a smaller file?</td>', 'Wow, very dramatic sky.  Looks a little pixelated though.  Was this enlarged from a smaller file?', '2006-11-01 15:45:23.000000', NULL, 1),
(2985210, 418656, 58567, '<td valign="top">Yep...has all the elements...couldn''t you have worked a snake in somewhere?  Good balance...well constructed photographically</td>', 'Yep...has all the elements...couldn''t you have worked a snake in somewhere?  Good balance...well constructed photographically', '2006-11-01 15:45:26.000000', NULL, 1),
(2985217, 419440, 30508, '<td valign="top">I love the black and white treatment of this.  Nice and contrasty.</td>', 'I love the black and white treatment of this.  Nice and contrasty.', '2006-11-01 15:45:55.000000', NULL, 1),
(2985222, 420706, 58567, '<td valign="top">Good composition....perhaps a little overworked for my taste</td>', 'Good composition....perhaps a little overworked for my taste', '2006-11-01 15:46:09.000000', NULL, 1),
(2985226, 419326, 58567, '<td valign="top">Good soft lighting</td>', 'Good soft lighting', '2006-11-01 15:46:38.000000', NULL, 1),
(2985229, 419496, 30508, '<td valign="top">Seems like this belongs in the portrait challenge.  I probably would have given it a 5 as I like the composition and story, but it seems a little out of focus.</td>', 'Seems like this belongs in the portrait challenge.  I probably would have given it a 5 as I like the composition and story, but it seems a little out of focus.', '2006-11-01 15:46:52.000000', NULL, 1),
(2985231, 418933, 64175, '<td valign="top">I like the leading lines effect of this composition.</td>', 'I like the leading lines effect of this composition.', '2006-11-01 15:47:01.000000', NULL, 1),
(2985232, 420597, 58567, '<td valign="top">Nice light on dark contrast work</td>', 'Nice light on dark contrast work', '2006-11-01 15:47:14.000000', NULL, 1),
(2985237, 420736, 58567, '<td valign="top">Well composed</td>', 'Well composed', '2006-11-01 15:47:42.000000', NULL, 1),
(2985243, 419095, 58567, '<td valign="top">Spectacular....you can feel the power of the water...nicely composed and processed</td>', 'Spectacular....you can feel the power of the water...nicely composed and processed', '2006-11-01 15:48:28.000000', NULL, 1),
(2985250, 420404, 30508, '<td valign="top">Way too small to fairly judge.</td>', 'Way too small to fairly judge.', '2006-11-01 15:49:18.000000', NULL, 1),
