(2985318, 421107, 31443, '<td valign="top">A house and some trees :) very nice dof the light is just perfect..</td>', 'A house and some trees :) very nice dof the light is just perfect..', '2006-11-01 15:58:42.000000', NULL, 1),
(2985320, 419432, 31829, '<td valign="top">I''m sorry, this is just to small to really evaluate.</td>', 'I''m sorry, this is just to small to really evaluate.', '2006-11-01 15:59:06.000000', NULL, 1),
(2985322, 420194, 30508, '<td valign="top">This is stunning!  The leaves in the foreground give this an almost magical quality, especially when combined with the blurred water.  A 10 and a fav!</td>', 'This is stunning!  The leaves in the foreground give this an almost magical quality, especially when combined with the blurred water.  A 10 and a fav!', '2006-11-01 15:59:17.000000', NULL, 1),
