(2987843, 420568, 66398, '<td valign="top">composition colors and lighting excellent<br/>idea and execution great. 9</td>', 'composition colors and lighting excellentidea and execution great. 9', '2006-11-02 03:29:08.000000', NULL, 1),
(2987857, 417545, 66398, '<td valign="top">Does not meet either challenge.  This is a portrait in portrait orientation.  Its not a bad photo though.  This man looks interesting.... someone I might want to listen to.  I''m sure he has some very interesting stories.</td>', 'Does not meet either challenge.  This is a portrait in portrait orientation.  Its not a bad photo though.  This man looks interesting.... someone I might want to listen to.  I''m sure he has some very interesting stories.', '2006-11-02 03:37:24.000000', NULL, 1),
(2987859, 420908, 66398, '<td valign="top">I''d be willing to bet money that there''s not a photo out there anywhere that could do justice to being there and seeing the real thing.  This might be as close as it gets though.  Nice job.</td>', 'I''d be willing to bet money that there''s not a photo out there anywhere that could do justice to being there and seeing the real thing.  This might be as close as it gets though.  Nice job.', '2006-11-02 03:42:00.000000', NULL, 1),
(2987868, 417720, 33352, '<td valign="top">Good perspective and color....6</td>', 'Good perspective and color....6', '2006-11-02 03:49:56.000000', NULL, 1),
(2987873, 419989, 33352, '<td valign="top">Very pretty scene, and well captured, the left to right of the subject in a potrait orientation does not quite work for me....7bumping...8</td>', 'Very pretty scene, and well captured, the left to right of the subject in a potrait orientation does not quite work for me....7bumping...8', '2006-11-02 03:52:46.000000', NULL, 1),
(2987940, 418280, 32161, '<td valign="top">Love the sky,lighting, mountains and tree''s. My only critisism is the forgroud..there is too much going on making it a tad messy imo. very nice other than that.</td>', 'Love the sky,lighting, mountains and tree''s. My only critisism is the forgroud..there is too much going on making it a tad messy imo. very nice other than that.', '2006-11-02 04:56:25.000000', NULL, 1),
(2987948, 420598, 32161, '<td valign="top">Really, really like this photo, would score it a lot higher for a different challenge, not really a landscape imo. lovely colors, focus etc</td>', 'Really, really like this photo, would score it a lot higher for a different challenge, not really a landscape imo. lovely colors, focus etc', '2006-11-02 05:03:54.000000', NULL, 1),
(2987981, 417350, 55956, '<td valign="top">very good idea. I like the frame. where you find it?</td>', 'very good idea. I like the frame. where you find it?', '2006-11-02 05:31:28.000000', NULL, 1),
(2988000, 420407, 41337, '<td valign="top">As far as waterfall shots are concern this looks good. I like how the water is very bright. Gets the highest score I give this subject (7).</td>', 'As far as waterfall shots are concern this looks good. I like how the water is very bright. Gets the highest score I give this subject (7).', '2006-11-02 05:48:01.000000', NULL, 1),
(2988008, 420964, 41337, '<td valign="top">Very interesting and unique looking shots. I hope this does well for you.</td>', 'Very interesting and unique looking shots. I hope this does well for you.', '2006-11-02 05:55:46.000000', NULL, 1),
(2988074, 419440, 48043, '<td valign="top">Nice, but focus a little off and picture leans to the right. Everything else good.</td>', 'Nice, but focus a little off and picture leans to the right. Everything else good.', '2006-11-02 06:38:04.000000', NULL, 1),
(2988097, 420801, 48043, '<td valign="top">Hmmmmm. A little over exposed where the sun is for my liking. As a result the sun looks huge. You may have done this for effect. If it was a little less I would give it a 10. So 9. Sort of looks like a nuclear explosion.</td>', 'Hmmmmm. A little over exposed where the sun is for my liking. As a result the sun looks huge. You may have done this for effect. If it was a little less I would give it a 10. So 9. Sort of looks like a nuclear explosion.', '2006-11-02 06:43:07.000000', NULL, 1),
(2988099, 420693, 49109, '<td valign="top">nice reflection, clouds are a bit greyish</td>', 'nice reflection, clouds are a bit greyish', '2006-11-02 06:43:33.000000', NULL, 1),
(2988104, 418665, 49109, '<td valign="top">very good use of the format, snow is a bit too bright in some areas</td>', 'very good use of the format, snow is a bit too bright in some areas', '2006-11-02 06:44:26.000000', NULL, 1),
(2988107, 420399, 49109, '<td valign="top">good colors</td>', 'good colors', '2006-11-02 06:45:35.000000', NULL, 1),
(2988121, 417396, 48043, '<td valign="top">Tricky. Sun is over exposed, sea is a little dark. I would have lowered the exposure to get the sun right, then use post processing to lighten up the sea. This was advanced editing, you could have dodged the sea to make it lighter and leave the top half alone.</td>', 'Tricky. Sun is over exposed, sea is a little dark. I would have lowered the exposure to get the sun right, then use post processing to lighten up the sea. This was advanced editing, you could have dodged the sea to make it lighter and leave the top half alone.', '2006-11-02 06:49:28.000000', NULL, 1),
(2988125, 419326, 48043, '<td valign="top">A little dark. Apart from that, really nice use of orientation.</td>', 'A little dark. Apart from that, really nice use of orientation.', '2006-11-02 06:50:41.000000', NULL, 1),
(2988134, 420187, 48043, '<td valign="top">Horizon leaning to left really badly.</td>', 'Horizon leaning to left really badly.', '2006-11-02 06:53:03.000000', NULL, 1),
(2988155, 418904, 62024, '<td valign="top">I would have liked this picture so much better if it was straight.</td>', 'I would have liked this picture so much better if it was straight.', '2006-11-02 06:59:45.000000', NULL, 1),
(2988219, 420564, 29537, '<td valign="top">very nice shot, perhaps better with a little crop in the sky</td>', 'very nice shot, perhaps better with a little crop in the sky', '2006-11-02 07:27:32.000000', NULL, 1),
(2988239, 419948, 60332, '<td valign="top">oops, wrong challenge?</td>', 'oops, wrong challenge?', '2006-11-02 07:38:57.000000', NULL, 1),
(2988274, 421039, 46870, '<td valign="top">wow great shot ,,,,,, love it hope for ribbon good luck 10</td>', 'wow great shot ,,,,,, love it hope for ribbon good luck 10', '2006-11-02 08:00:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
