INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2994168, 418665, 5792, '<td valign="top">Beautiful snow scene, great concept, not overexposed, very nice high contrast B&amp;W. Vertical is not true in this image. You can see that if the trees were corrected to vertical (tops tilted back to the left) that the end of the deck would be straightened as well. A curiosity, though, is that front railings would be made even more unbalanced than they already are. Not sure why that is or how to correct it.</td>', 'Beautiful snow scene, great concept, not overexposed, very nice high contrast B&W. Vertical is not true in this image. You can see that if the trees were corrected to vertical (tops tilted back to the left) that the end of the deck would be straightened as well. A curiosity, though, is that front railings would be made even more unbalanced than they already are. Not sure why that is or how to correct it.', '2006-11-03 14:01:41.000000', NULL, 1),
(2994170, 420645, 13207, '<td valign="top">Meets Challenge:2<br/>Technical:1<br/>Lighting:1<br/>Content:0<br/>Opinion:1</td>', 'Meets Challenge:2Technical:1Lighting:1Content:0Opinion:1', '2006-11-03 14:01:53.000000', NULL, 1),
