(2994469, 419432, 50034, '<td valign="top">Small jpeg...</td>', 'Small jpeg...', '2006-11-03 15:26:06.000000', NULL, 1),
(2994515, 419029, 50034, '<td valign="top">Orientation!?!  This does meet the challenge, but I am left wondering if you''re as much of a Newbie as I have been this past year.  It looks like you rotated the camera on-site, had issues with rotating the jpeg 90 degrees right in your computer.  If I''m correct, then simply do a right click on the jpeg itself, and left-click on the word, Edit.  Whatever default program that opens the jpeg should be able to rotate a quarter-turn to the right!  (I hope that didn''t appear "in-your-face" because you could have wanted it this way for some reason unknown to me, then it would be "in-my-face.")  :}</td>', 'Orientation!?!  This does meet the challenge, but I am left wondering if you''re as much of a Newbie as I have been this past year.  It looks like you rotated the camera on-site, had issues with rotating the jpeg 90 degrees right in your computer.  If I''m correct, then simply do a right click on the jpeg itself, and left-click on the word, Edit.  Whatever default program that opens the jpeg should be able to rotate a quarter-turn to the right!  (I hope that didn''t appear "in-your-face" because you could have wanted it this way for some reason unknown to me, then it would be "in-my-face.")  :}', '2006-11-03 15:35:03.000000', NULL, 1),
(2994536, 418278, 50034, '<td valign="top">Sorry, but I used to teacher school!  Spelling errors always "scream" at me and get a point deducted for each.  (-2 here.)  <b>Beautiful Autumn</b>  Other than that it would have been a six.</td>', 'Sorry, but I used to teacher school!  Spelling errors always "scream" at me and get a point deducted for each.  (-2 here.)  Beautiful Autumn  Other than that it would have been a six.', '2006-11-03 15:40:29.000000', NULL, 1),
