(2996074, 418944, 34938, '<td valign="top">I love the mood this image conveys...the light is eerie and cold...nice</td>', 'I love the mood this image conveys...the light is eerie and cold...nice', '2006-11-03 21:32:14.000000', NULL, 1),
(2996076, 420404, 34938, '<td valign="top">too small 2</td>', 'too small 2', '2006-11-03 21:32:49.000000', NULL, 1),
(2996078, 420745, 34938, '<td valign="top">wow...the water is really nice in this...I feel like I am there with your perspective...nice work</td>', 'wow...the water is really nice in this...I feel like I am there with your perspective...nice work', '2006-11-03 21:33:23.000000', NULL, 1),
(2996080, 419287, 34938, '<td valign="top">blurry...fun title though</td>', 'blurry...fun title though', '2006-11-03 21:34:01.000000', NULL, 1),
(2996082, 420194, 34938, '<td valign="top">love the longer exposure on this...a lovely image 8</td>', 'love the longer exposure on this...a lovely image 8', '2006-11-03 21:34:27.000000', NULL, 1),
(2996184, 419102, 45021, '<td valign="top">Love the sky and reflection though the foreground element does not do much for me.</td>', 'Love the sky and reflection though the foreground element does not do much for me.', '2006-11-03 22:15:45.000000', NULL, 1),
(2996190, 420514, 45021, '<td valign="top">Great colours and leading lines, very well composed.</td>', 'Great colours and leading lines, very well composed.', '2006-11-03 22:16:51.000000', NULL, 1),
(2996199, 419872, 45021, '<td valign="top">Good idea, I like that you have tried something different.  For me the time of day and therefore quality of light is just not right, I think early morning or late afternoon might have been more flattering.</td>', 'Good idea, I like that you have tried something different.  For me the time of day and therefore quality of light is just not right, I think early morning or late afternoon might have been more flattering.', '2006-11-03 22:18:19.000000', NULL, 1),
(2996209, 420447, 45021, '<td valign="top">Great colours and reflection and I like the inclusion of the kayaker, though for me it just doesn''t have a real wow factor.</td>', 'Great colours and reflection and I like the inclusion of the kayaker, though for me it just doesn''t have a real wow factor.', '2006-11-03 22:20:09.000000', NULL, 1),
(2996212, 420697, 45021, '<td valign="top">Looks a little flat and the silhouettes you have chosen are not the most flattering choices, they are a bit messy.</td>', 'Looks a little flat and the silhouettes you have chosen are not the most flattering choices, they are a bit messy.', '2006-11-03 22:21:15.000000', NULL, 1),
(2996215, 420214, 45021, '<td valign="top">I like the composition, though there maybe a tad too much foreground.  The colours look a tad oversaturated and therefore not quite real.</td>', 'I like the composition, though there maybe a tad too much foreground.  The colours look a tad oversaturated and therefore not quite real.', '2006-11-03 22:22:36.000000', NULL, 1),
(2996219, 420806, 45021, '<td valign="top">Has the makings of a great shot, love the layers of land though for me the bottom third being out of focus just doesn''t work for me.</td>', 'Has the makings of a great shot, love the layers of land though for me the bottom third being out of focus just doesn''t work for me.', '2006-11-03 22:23:49.000000', NULL, 1),
(2996223, 419029, 45021, '<td valign="top">I know you are going to be told this a lot but why did you choose to display it this way, just makes it confusing and dificult to judge the quality of the shot.</td>', 'I know you are going to be told this a lot but why did you choose to display it this way, just makes it confusing and dificult to judge the quality of the shot.', '2006-11-03 22:25:13.000000', NULL, 1),
(2996226, 419524, 45021, '<td valign="top">Love the light in this, it is amazing.  Though unfortunately there is no real focal point in the shot.</td>', 'Love the light in this, it is amazing.  Though unfortunately there is no real focal point in the shot.', '2006-11-03 22:26:01.000000', NULL, 1),
(2996229, 420168, 45021, '<td valign="top">I actually like the abstract/surreal feel the jarred exposure gives.  The colours and movement create quite a mood.  I think this will end up being a love/hate type of shot, though from me at least it is a love.</td>', 'I actually like the abstract/surreal feel the jarred exposure gives.  The colours and movement create quite a mood.  I think this will end up being a love/hate type of shot, though from me at least it is a love.', '2006-11-03 22:27:25.000000', NULL, 1),
(2996238, 418297, 45021, '<td valign="top">Sorry but there is nothing in this shot to keep the viewers attention, the grass and leaves in the foreground are just not impressive enough.  It might have worked by getting down to a low perspective and get up close to a leaf and let it fill the bottom third.</td>', 'Sorry but there is nothing in this shot to keep the viewers attention, the grass and leaves in the foreground are just not impressive enough.  It might have worked by getting down to a low perspective and get up close to a leaf and let it fill the bottom third.', '2006-11-03 22:29:29.000000', NULL, 1),
(2996241, 418944, 45021, '<td valign="top">Great composition and mood.</td>', 'Great composition and mood.', '2006-11-03 22:30:14.000000', NULL, 1),
