(2998359, 420545, 66398, '<td valign="top">that you''re in this place. Please let me stay and rest in your holiness. Word of God speak. (It''s a song.. did you know it when you chose the title?)<br/>The photo fits it.</td>', 'that you''re in this place. Please let me stay and rest in your holiness. Word of God speak. (It''s a song.. did you know it when you chose the title?)The photo fits it.', '2006-11-04 17:51:27.000000', NULL, 1),
(2998362, 420127, 66398, '<td valign="top">I think a little darker would work better.  Good composition just a bit washed out.</td>', 'I think a little darker would work better.  Good composition just a bit washed out.', '2006-11-04 17:53:20.000000', NULL, 1),
(2998377, 420447, 66398, '<td valign="top">Oh nice colors.  Autumn photos have been too much for me lately but, this is nice with the bright red and blue in it to break them up a bit.  Nice!!</td>', 'Oh nice colors.  Autumn photos have been too much for me lately but, this is nice with the bright red and blue in it to break them up a bit.  Nice!!', '2006-11-04 17:57:39.000000', NULL, 1),
