(2998387, 420404, 66398, '<td valign="top">wow this is small</td>', 'wow this is small', '2006-11-04 18:00:29.000000', NULL, 1),
(2998416, 421142, 66398, '<td valign="top">Very nice. I like the contrast on the rocks.  I wouldn''t crop this photo but, this might have been a bit better (a re-shoot?) if you had zoomed a little more to get just a little less sky or maybe pan a little lower (not sure if what was there would have been too distracting).8</td>', 'Very nice. I like the contrast on the rocks.  I wouldn''t crop this photo but, this might have been a bit better (a re-shoot?) if you had zoomed a little more to get just a little less sky or maybe pan a little lower (not sure if what was there would have been too distracting).8', '2006-11-04 18:10:59.000000', NULL, 1),
(2998421, 419336, 58567, '<td valign="top">Delicious shot...well composed...love the bleached signs of high-water...9</td>', 'Delicious shot...well composed...love the bleached signs of high-water...9', '2006-11-04 18:12:25.000000', NULL, 1),
(2998426, 420070, 58567, '<td valign="top">Race back to grab this shot again for the reflections challenge....nicely composed!</td>', 'Race back to grab this shot again for the reflections challenge....nicely composed!', '2006-11-04 18:13:23.000000', NULL, 1),
