(2998480, 417471, 58567, '<td valign="top">Top notch composition....You''ve got the rule of thirds going well...is this the Mekong?....8</td>', 'Top notch composition....You''ve got the rule of thirds going well...is this the Mekong?....8', '2006-11-04 18:26:17.000000', NULL, 1),
(2998484, 420491, 66398, '<td valign="top">Taken from a car or train window that had a spot on it?... It''s a bit small. But it is a landscape and it is in portrait mode... composition is okay, focus could be more crisp but you were moving after all so that''s the reason it isn''t I guess.</td>', 'Taken from a car or train window that had a spot on it?... It''s a bit small. But it is a landscape and it is in portrait mode... composition is okay, focus could be more crisp but you were moving after all so that''s the reason it isn''t I guess.', '2006-11-04 18:27:15.000000', NULL, 1),
(2998485, 417288, 58567, '<td valign="top">This is a good bokeh shot...works well for the landscape challenge this time as well....7</td>', 'This is a good bokeh shot...works well for the landscape challenge this time as well....7', '2006-11-04 18:27:18.000000', NULL, 1),
