INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3004302, 418665, 42891, '<td valign="top">Looks cold I like the snow on the trees</td>', 'Looks cold I like the snow on the trees', '2006-11-06 00:00:17.000000', NULL, 1),
(3004435, 420407, 68030, '<td valign="top">breathtaking</td>', 'breathtaking', '2006-11-06 00:33:42.000000', NULL, 1),
(3004562, 420447, 59564, '<td valign="top">Great reflections.  They may be a little too much though.  They may detract a little from the subject.</td>', 'Great reflections.  They may be a little too much though.  They may detract a little from the subject.', '2006-11-06 01:10:13.000000', NULL, 1),
(3004568, 420545, 59564, '<td valign="top">Very nice reflections.</td>', 'Very nice reflections.', '2006-11-06 01:11:13.000000', NULL, 1),
(3004581, 420653, 59564, '<td valign="top">The colors are great.</td>', 'The colors are great.', '2006-11-06 01:12:56.000000', NULL, 1),
(3004643, 420564, 32876, '<td valign="top">Nice Shot</td>', 'Nice Shot', '2006-11-06 01:35:59.000000', NULL, 1),
(3004648, 419885, 59564, '<td valign="top">The colors seem a bit muted but I like the effect that it creates.  Very moody.</td>', 'The colors seem a bit muted but I like the effect that it creates.  Very moody.', '2006-11-06 01:37:34.000000', NULL, 1),
(3004649, 421038, 59564, '<td valign="top">Little grainy but I like the sky colors.</td>', 'Little grainy but I like the sky colors.', '2006-11-06 01:38:18.000000', NULL, 1),
(3004650, 420693, 59564, '<td valign="top">I like the reflection.  I don''t know if I like the fact that is splits the image directly in half.</td>', 'I like the reflection.  I don''t know if I like the fact that is splits the image directly in half.', '2006-11-06 01:39:06.000000', NULL, 1),
(3004680, 420575, 59564, '<td valign="top">I feel like I would like to see a little more of the building.</td>', 'I feel like I would like to see a little more of the building.', '2006-11-06 01:53:00.000000', NULL, 1),
(3004684, 420401, 59564, '<td valign="top">Very nice colors.</td>', 'Very nice colors.', '2006-11-06 01:53:16.000000', NULL, 1),
(3004685, 420903, 59564, '<td valign="top">I like the colors here and the space created by the sky.</td>', 'I like the colors here and the space created by the sky.', '2006-11-06 01:53:43.000000', NULL, 1),
(3004690, 420757, 59564, '<td valign="top">The fog or haze really adds to the image.</td>', 'The fog or haze really adds to the image.', '2006-11-06 01:54:40.000000', NULL, 1),
(3004694, 420831, 59564, '<td valign="top">I love the sky.  The slight tilt is a little distracting but there is no way I''m going to be a ''straighten'' nazi and vote this wonderful photo down because of it.</td>', 'I love the sky.  The slight tilt is a little distracting but there is no way I''m going to be a ''straighten'' nazi and vote this wonderful photo down because of it.', '2006-11-06 01:55:53.000000', NULL, 1),
(3004703, 420864, 59564, '<td valign="top">Great colors.  Maybe just a bit to much yellow.</td>', 'Great colors.  Maybe just a bit to much yellow.', '2006-11-06 01:59:53.000000', NULL, 1),
(3004865, 419816, 64933, '<td valign="top">Beautiful subject, POV, &amp; lighting! The leaves are a bit too sharp though I''m sorry to say.</td>', 'Beautiful subject, POV, & lighting! The leaves are a bit too sharp though I''m sorry to say.', '2006-11-06 03:57:19.000000', NULL, 1),
(3004869, 421007, 64933, '<td valign="top">Perfect subject &amp; such wonderful colors. I love how the branch drapes over the slanted bridge. It would have made it that much more brilliant if the tree''s leaves were sharper and didn''t seem to fade into the blue sky as much. I don''t think that that perticular border type does anything for the picture either.</td>', 'Perfect subject & such wonderful colors. I love how the branch drapes over the slanted bridge. It would have made it that much more brilliant if the tree''s leaves were sharper and didn''t seem to fade into the blue sky as much. I don''t think that that perticular border type does anything for the picture either.', '2006-11-06 04:07:59.000000', NULL, 1),
(3004870, 420032, 64933, '<td valign="top">Great picture idea- love the subject but I think that the color of the tree bark &amp; ground contrast against the almost too much.</td>', 'Great picture idea- love the subject but I think that the color of the tree bark & ground contrast against the almost too much.', '2006-11-06 04:10:18.000000', NULL, 1),
(3004872, 420442, 64933, '<td valign="top">I love the idea with the fog and all the trees in a row, but it is almost too grayscale and orderly to hold my attention.</td>', 'I love the idea with the fog and all the trees in a row, but it is almost too grayscale and orderly to hold my attention.', '2006-11-06 04:11:54.000000', NULL, 1),
(3004875, 421055, 64933, '<td valign="top">Beautiful... I love everything about it except the fact that it is a tiny bit over sharpened. I could most tell on the part of the fence where it is leading away.</td>', 'Beautiful... I love everything about it except the fact that it is a tiny bit over sharpened. I could most tell on the part of the fence where it is leading away.', '2006-11-06 04:13:36.000000', NULL, 1),
(3004913, 420190, 58567, '<td valign="top">Nice sepia....good angles...adeptly done...8</td>', 'Nice sepia....good angles...adeptly done...8', '2006-11-06 04:44:35.000000', NULL, 1),
(3004916, 418665, 58567, '<td valign="top">Pourquoi est-ce-que sans titre?  Nice shot....looks bloody cold!  7</td>', 'Pourquoi est-ce-que sans titre?  Nice shot....looks bloody cold!  7', '2006-11-06 04:46:48.000000', NULL, 1),
(3004920, 418910, 58567, '<td valign="top">Just...WOW...perfect composition....my only 10!</td>', 'Just...WOW...perfect composition....my only 10!', '2006-11-06 04:48:18.000000', NULL, 1),
(3004926, 420745, 58567, '<td valign="top">Surreal....beautifully captured and tricked up</td>', 'Surreal....beautifully captured and tricked up', '2006-11-06 04:51:11.000000', NULL, 1),
(3004975, 420915, 22689, '<td valign="top">It seems an interesting place and the reflections are really nice but the composition is a bit poor , the portrait orientation doesn''t work very well , the trees are too centered.</td>', 'It seems an interesting place and the reflections are really nice but the composition is a bit poor , the portrait orientation doesn''t work very well , the trees are too centered.', '2006-11-06 05:17:26.000000', NULL, 1),
(3004981, 417933, 22689, '<td valign="top">I don''t like the border (but never vote lower because of that :-) ...) Nice autumn/fall colors and DOF.</td>', 'I don''t like the border (but never vote lower because of that :-) ...) Nice autumn/fall colors and DOF.', '2006-11-06 05:20:07.000000', NULL, 1),
(3004986, 419524, 22689, '<td valign="top">Very nice ! The way you show the different textures is excellent , it''s like I could be able to touch them , the colors are warm.<br/>my vote : 8</td>', 'Very nice ! The way you show the different textures is excellent , it''s like I could be able to touch them , the colors are warm.my vote : 8', '2006-11-06 05:26:10.000000', NULL, 1),
(3005005, 417472, 22689, '<td valign="top">And the winner is ... ! What a terrific photo ! My fav in this moment : the composition is perfect , nice colors and saturation and the flag adds the final touch. Very good job !<br/>my vote : 10</td>', 'And the winner is ... ! What a terrific photo ! My fav in this moment : the composition is perfect , nice colors and saturation and the flag adds the final touch. Very good job !my vote : 10', '2006-11-06 05:43:33.000000', NULL, 1),
(3005017, 420961, 68134, '<td valign="top">this photo is a great reprensation of the energy within the skies</td>', 'this photo is a great reprensation of the energy within the skies', '2006-11-06 05:56:47.000000', NULL, 1),
(3005023, 419974, 68134, '<td valign="top">this photo translates a sense of mystery, the still time before spring.</td>', 'this photo translates a sense of mystery, the still time before spring.', '2006-11-06 06:01:01.000000', NULL, 1),
(3005029, 420642, 68134, '<td valign="top">the angles of the grasses against the outline of the hills creates a lovley composition</td>', 'the angles of the grasses against the outline of the hills creates a lovley composition', '2006-11-06 06:07:31.000000', NULL, 1),
(3005037, 418193, 68134, '<td valign="top">this photo allows you to not only see the trees, but the land in which the trees stand.</td>', 'this photo allows you to not only see the trees, but the land in which the trees stand.', '2006-11-06 06:11:47.000000', NULL, 1),
(3005038, 420964, 68134, '<td valign="top">in this image its easy to recognize the relationship between the mountains and the trees</td>', 'in this image its easy to recognize the relationship between the mountains and the trees', '2006-11-06 06:14:51.000000', NULL, 1),
(3005147, 419432, 61679, '<td valign="top">Back to comment:  This image is much smaller than what is allowed for a challenge.  The longest side of your image should be 640 pixels.  When your image is this small, it is hard to see the details and judge the quality of the image.  Because of that, many people will give a low vote and move on without really looking.</td>', 'Back to comment:  This image is much smaller than what is allowed for a challenge.  The longest side of your image should be 640 pixels.  When your image is this small, it is hard to see the details and judge the quality of the image.  Because of that, many people will give a low vote and move on without really looking.', '2006-11-06 07:13:35.000000', NULL, 1),
(3005148, 420404, 61679, '<td valign="top">Back to comment:  This image is much smaller than what is allowed for a challenge.  The longest side of your image should be 640 pixels.  When your image is this small, it is hard to see the details and judge the quality of the image.  Because of that, many people will give a low vote and move on without really looking.</td>', 'Back to comment:  This image is much smaller than what is allowed for a challenge.  The longest side of your image should be 640 pixels.  When your image is this small, it is hard to see the details and judge the quality of the image.  Because of that, many people will give a low vote and move on without really looking.', '2006-11-06 07:13:42.000000', NULL, 1),
