(3010349, 421040, 67240, '<td valign="top">The cameraphone ruins it for me. Should have had one drinking a beer and it would have been perfect.</td>', 'The cameraphone ruins it for me. Should have had one drinking a beer and it would have been perfect.', '2006-11-07 13:02:33.000000', NULL, 1),
