(3010694, 418487, 67535, '<td valign="top">very cool shot... i love the frame and the blues.</td>', 'very cool shot... i love the frame and the blues.', '2006-11-07 14:33:12.000000', NULL, 1),
(3010714, 420631, 66952, '<td valign="top">It looks like the scene on the ground is dark and a bit featureless, but the sky is blown out.</td>', 'It looks like the scene on the ground is dark and a bit featureless, but the sky is blown out.', '2006-11-07 14:39:03.000000', NULL, 1),
(3010721, 420223, 66952, '<td valign="top">The power lines, fences, light poles, and cars distract from the interesting sky. It might have worked better to find a higher vantage point, and shoot over the obstructions.</td>', 'The power lines, fences, light poles, and cars distract from the interesting sky. It might have worked better to find a higher vantage point, and shoot over the obstructions.', '2006-11-07 14:41:01.000000', NULL, 1),
(3010725, 417911, 66952, '<td valign="top">It''s an interesting subject, but the post-processing is really over the top.</td>', 'It''s an interesting subject, but the post-processing is really over the top.', '2006-11-07 14:42:50.000000', NULL, 1),
(3010730, 421148, 66952, '<td valign="top">It doesn''t work for me. The processing or whatever made it too hard to figure out what I was looking at. It might do better in an abstract challenge.</td>', 'It doesn''t work for me. The processing or whatever made it too hard to figure out what I was looking at. It might do better in an abstract challenge.', '2006-11-07 14:45:16.000000', NULL, 1),
(3010733, 420172, 66952, '<td valign="top">I''m not sure what you did to superimpose the factory on top of the tree. I think the factory by itself would have been more interesting, though.</td>', 'I''m not sure what you did to superimpose the factory on top of the tree. I think the factory by itself would have been more interesting, though.', '2006-11-07 14:46:37.000000', NULL, 1),
(3010753, 418067, 67240, '<td valign="top">Moon looks strange, but nice shot.</td>', 'Moon looks strange, but nice shot.', '2006-11-07 14:53:48.000000', NULL, 1),
